alter table public.categories add column if not exists parent_id uuid references public.categories(id) on delete restrict;
alter table public.categories add column if not exists is_selectable boolean not null default true;
alter table public.categories add column if not exists sort_order smallint not null default 0;
alter table public.categories add column if not exists search_terms text[] not null default '{}'::text[];

create index if not exists categories_parent_idx on public.categories(parent_id);
create index if not exists categories_parent_sort_idx on public.categories(parent_id,sort_order,name);
create index if not exists categories_search_terms_idx on public.categories using gin(search_terms);

