create table if not exists public.vehicle_catalogue_make_aliases(
 provider text not null,
 source_make text not null,
 canonical_make text not null,
 display_name text not null,
 created_at timestamptz not null default now(),
 primary key(provider,source_make)
);
comment on table public.vehicle_catalogue_make_aliases is 'Presentation aliases for provider make names. Raw imported vehicle rows are never overwritten.';
alter table public.vehicle_catalogue_make_aliases enable row level security;
insert into public.vehicle_catalogue_make_aliases(provider,source_make,canonical_make,display_name) values ('dft','MERCEDES','MERCEDES-BENZ','Mercedes-Benz') on conflict(provider,source_make) do update set canonical_make=excluded.canonical_make,display_name=excluded.display_name;
insert into public.vehicle_catalogue_make_aliases(provider,source_make,canonical_make,display_name) values ('dft','MERCEDES-BENZ','MERCEDES-BENZ','Mercedes-Benz') on conflict(provider,source_make) do update set canonical_make=excluded.canonical_make,display_name=excluded.display_name;

drop policy if exists "vehicle catalogue make aliases public read" on public.vehicle_catalogue_make_aliases;
create policy "vehicle catalogue make aliases public read" on public.vehicle_catalogue_make_aliases for select to anon,authenticated using(true);
drop policy if exists "vehicle catalogue make aliases admin insert" on public.vehicle_catalogue_make_aliases;
create policy "vehicle catalogue make aliases admin insert" on public.vehicle_catalogue_make_aliases for insert to authenticated with check(private.is_admin());
drop policy if exists "vehicle catalogue make aliases admin update" on public.vehicle_catalogue_make_aliases;
create policy "vehicle catalogue make aliases admin update" on public.vehicle_catalogue_make_aliases for update to authenticated using(private.is_admin()) with check(private.is_admin());
drop policy if exists "vehicle catalogue make aliases admin delete" on public.vehicle_catalogue_make_aliases;
create policy "vehicle catalogue make aliases admin delete" on public.vehicle_catalogue_make_aliases for delete to authenticated using(private.is_admin());
grant select on public.vehicle_catalogue_make_aliases to anon,authenticated;
grant insert,update,delete on public.vehicle_catalogue_make_aliases to authenticated;

create or replace function public.vehicle_catalogue_model_map_json() returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('make',q.make,'modelFamily',q.model_family) order by q.make,q.model_family),'[]'::jsonb)
 from (select distinct coalesce(a.canonical_make,v.make) as make,v.model_family from public.vehicle_catalogue_variants v left join public.vehicle_catalogue_make_aliases a on a.provider=v.provider and a.source_make=v.make where v.provider='dft' and v.body_type='Cars') q;
$$;
create or replace function public.vehicle_catalogue_years_for_model(p_make text,p_model text) returns table(year_first_used smallint) language sql stable set search_path='' as $$
 select distinct y.year_first_used from public.vehicle_catalogue_variants v left join public.vehicle_catalogue_make_aliases a on a.provider=v.provider and a.source_make=v.make join public.vehicle_catalogue_years y on y.variant_id=v.id where v.provider='dft' and v.body_type='Cars' and coalesce(a.canonical_make,v.make)=p_make and v.model_family=p_model order by y.year_first_used desc;
$$;
create or replace function public.vehicle_catalogue_variants_for_model_year(p_make text,p_model text,p_year smallint) returns table(id uuid,variant text) language sql stable set search_path='' as $$
 select distinct v.id,v.variant from public.vehicle_catalogue_variants v left join public.vehicle_catalogue_make_aliases a on a.provider=v.provider and a.source_make=v.make join public.vehicle_catalogue_years y on y.variant_id=v.id where v.provider='dft' and v.body_type='Cars' and coalesce(a.canonical_make,v.make)=p_make and v.model_family=p_model and y.year_first_used=p_year order by v.variant;
$$;
